package com.recgombak.batterymonitor;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.media.*;import android.net.Uri;import android.net.wifi.WifiManager;import android.os.*;import android.provider.Settings;import android.view.Gravity;import android.widget.*;import org.json.JSONObject;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;

public class MainActivity extends Activity{
 private final Handler ui=new Handler(Looper.getMainLooper());private final Map<String,DeviceInfo> devices=Collections.synchronizedMap(new HashMap<>());private final Set<String>alerted=new HashSet<>();private LinearLayout root,list;private TextView subtitle,selfStatus;private volatile boolean listening;private DatagramSocket socket;private WifiManager.MulticastLock lock;private boolean weakOnly=false;
 @Override protected void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},44);if(Prefs.getRole(this).isEmpty())chooseRole();else launch();}
 private void chooseRole(){new AlertDialog.Builder(this).setTitle("Pilih mod peranti").setMessage("MONITOR untuk telefon cikgu. TABLET untuk tablet murid.").setCancelable(false).setPositiveButton("MONITOR",(d,w)->{Prefs.setRole(this,"monitor");launch();}).setNegativeButton("TABLET",(d,w)->{Prefs.setRole(this,"tablet");launch();}).show();}
 private void launch(){buildUi();if(Prefs.isEnabled(this))startBatteryService();if("monitor".equals(Prefs.getRole(this)))startListener();ui.post(refresh);}
 private void buildUi(){ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(24));root.setBackgroundColor(Color.rgb(247,248,250));s.addView(root);root.addView(tv("REC Battery Monitor",27,Color.rgb(15,23,42),true));root.addView(tv("Mod "+Prefs.getRole(this).toUpperCase(),13,Color.DKGRAY,true));if("monitor".equals(Prefs.getRole(this)))buildMonitor();else buildTablet();TextView foot=tv("Develop by cigunofal",12,Color.GRAY,true);foot.setGravity(Gravity.CENTER);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.setMargins(0,dp(24),0,dp(8));foot.setLayoutParams(fp);root.addView(foot);setContentView(s);}
 private void buildTablet(){LinearLayout c=card();c.addView(tv("TABLET INI",12,Color.GRAY,true));TextView name=tv(Prefs.getName(this),24,Color.rgb(15,23,42),true);c.addView(name);Button rename=button("Tukar nama");rename.setOnClickListener(v->rename(name));c.addView(rename);selfStatus=tv("Pemantauan aktif",17,Color.rgb(22,120,60),true);c.addView(selfStatus);root.addView(c);Button overlay=button("Benarkan paparan MASA TAMAT atas app lain");overlay.setOnClickListener(v->openOverlaySettings());root.addView(overlay);Button bg=button("Benarkan berjalan di background");bg.setOnClickListener(v->openBatterySettings());root.addView(bg);Button mode=button("Tukar ke Mod Monitor");mode.setOnClickListener(v->{Prefs.setRole(this,"monitor");recreate();});root.addView(mode);root.addView(tv("Tablet ini hanya menghantar status bateri. Ia tidak memaparkan bateri tablet lain.",13,Color.GRAY,false));}
 private void buildMonitor(){subtitle=tv("Mengesan tablet dalam WLAN…",14,Color.DKGRAY,false);root.addView(subtitle);LinearLayout actions=new LinearLayout(this);Button ref=button("↻ Refresh Semua");ref.setOnClickListener(v->sendSimpleCommand("ALL","refresh",0));actions.addView(ref,new LinearLayout.LayoutParams(0,-2,1));Button weak=button("Tablet Lemah");weak.setOnClickListener(v->{weakOnly=!weakOnly;weak.setText(weakOnly?"Tunjuk Semua":"Tablet Lemah");render();});actions.addView(weak,new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);Button settings=button("⚙ Tetapan Monitor");settings.setOnClickListener(v->settingsDialog());root.addView(settings);root.addView(tv("TABLET DALAM WLAN",13,Color.DKGRAY,true));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);Button hidden=button("Pulihkan tablet yang dipadam");hidden.setOnClickListener(v->{Prefs.clearHidden(this);Toast.makeText(this,"Senarai tablet dipulihkan",Toast.LENGTH_SHORT).show();});root.addView(hidden);Button mode=button("Tukar ke Mod Tablet");mode.setOnClickListener(v->{Prefs.setRole(this,"tablet");recreate();});root.addView(mode);}
 private void settingsDialog(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(24),0,dp(24),0);EditText threshold=num(String.valueOf(Prefs.getThreshold(this)));box.addView(label("Penggera berbunyi pada / bawah (%)"));box.addView(threshold);EditText interval=num(String.valueOf(Prefs.getInterval(this)));box.addView(label("Kemas kini setiap (saat, minimum 5)"));box.addView(interval);EditText alarmSec=num(String.valueOf(Prefs.getAlarmSeconds(this)));box.addView(label("Tempoh bunyi penggera (saat, 1–60)"));box.addView(alarmSec);CheckBox schedule=new CheckBox(this);schedule.setText("Gunakan jadual pemantauan untuk SEMUA tablet");schedule.setChecked(Prefs.scheduleOn(this));box.addView(schedule);Button start=button("Mula: "+timeText(Prefs.getStartMin(this))),end=button("Tamat: "+timeText(Prefs.getEndMin(this)));final int[] times={Prefs.getStartMin(this),Prefs.getEndMin(this)};start.setOnClickListener(v->pickTime(times,0,start,"Mula: "));end.setOnClickListener(v->pickTime(times,1,end,"Tamat: "));box.addView(start);box.addView(end);box.addView(tv("Apabila Simpan ditekan, jadual ini dihantar kepada semua tablet versi terbaru dalam WLAN.",12,Color.GRAY,false));new AlertDialog.Builder(this).setTitle("Tetapan Monitor").setView(box).setPositiveButton("Simpan",(d,w)->{try{Prefs.setThreshold(this,Integer.parseInt(threshold.getText().toString()));}catch(Exception ignored){}try{Prefs.setInterval(this,Integer.parseInt(interval.getText().toString()));}catch(Exception ignored){}try{Prefs.setAlarmSeconds(this,Integer.parseInt(alarmSec.getText().toString()));}catch(Exception ignored){}Prefs.setScheduleOn(this,schedule.isChecked());Prefs.setSchedule(this,times[0],times[1]);sendSchedule(schedule.isChecked(),times[0],times[1]);alerted.clear();Toast.makeText(this,"Tetapan disimpan dan jadual dihantar ke semua tablet",Toast.LENGTH_LONG).show();}).setNegativeButton("Batal",null).show();}
 private EditText num(String s){EditText e=new EditText(this);e.setInputType(2);e.setText(s);return e;}private TextView label(String s){return tv(s,13,Color.DKGRAY,true);}private void pickTime(int[] a,int idx,Button b,String pre){int m=a[idx];new TimePickerDialog(this,(v,h,min)->{a[idx]=h*60+min;b.setText(pre+timeText(a[idx]));},m/60,m%60,false).show();}private String timeText(int m){int h=m/60,min=m%60;String ap=h>=12?"PM":"AM";int hh=h%12;if(hh==0)hh=12;return String.format(Locale.US,"%d:%02d %s",hh,min,ap);}
 private void rename(TextView v){EditText i=new EditText(this);i.setText(Prefs.getName(this));new AlertDialog.Builder(this).setTitle("Nama tablet").setView(i).setPositiveButton("Simpan",(d,w)->{String n=i.getText().toString().trim();if(!n.isEmpty()){Prefs.setName(this,n);v.setText(n);}}).setNegativeButton("Batal",null).show();}
 private void openOverlaySettings(){if(Build.VERSION.SDK_INT<23){Toast.makeText(this,"Android ini tidak memerlukan kebenaran overlay berasingan",Toast.LENGTH_LONG).show();return;}try{Intent i=new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()));startActivity(i);}catch(Exception e){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION));}}
 private void openBatterySettings(){Intent i=new Intent();try{if(Build.VERSION.SDK_INT>=23){i.setAction(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS);startActivity(i);Toast.makeText(this,"Cari REC Battery Monitor dan matikan optimisation / pilih Unrestricted",Toast.LENGTH_LONG).show();return;}}catch(Exception ignored){}try{i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()));startActivity(i);}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}}
 private void startBatteryService(){Intent i=new Intent(this,BatteryBroadcastService.class);try{if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception ignored){}}
 private void startListener(){if(listening)return;listening=true;try{WifiManager w=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);lock=w.createMulticastLock("recBatteryLock");lock.setReferenceCounted(false);lock.acquire();}catch(Exception ignored){}new Thread(this::listen).start();}
 private void listen(){try{socket=new DatagramSocket(null);socket.setReuseAddress(true);socket.setBroadcast(true);socket.bind(new InetSocketAddress(BatteryBroadcastService.PORT));socket.setSoTimeout(3000);byte[] buf=new byte[2048];while(listening){try{DatagramPacket p=new DatagramPacket(buf,buf.length);socket.receive(p);JSONObject o=new JSONObject(new String(p.getData(),p.getOffset(),p.getLength(),StandardCharsets.UTF_8));String app=o.optString("app");if(!app.startsWith("REC_BATTERY_V"))continue;String id=o.optString("id");if(id.isEmpty()||id.equals(Prefs.getId(this))||Prefs.getHidden(this).contains(id))continue;DeviceInfo d=devices.get(id);if(d==null)d=new DeviceInfo();d.id=id;d.name=o.optString("name","Tablet");d.model=o.optString("model","Android");d.battery=o.optInt("battery",-1);d.charging=o.optBoolean("charging",false);d.timerEnd=o.optLong("timerEnd",0);d.lastSeen=System.currentTimeMillis();d.ip=p.getAddress().getHostAddress();devices.put(id,d);}catch(SocketTimeoutException ignored){}catch(Exception ignored){}}}catch(Exception ignored){}}
 private void sendSimpleCommand(String target,String cmd,int minutes){sendPacketCommand(target,cmd,minutes,false,0,0);}
 private void sendSchedule(boolean enabled,int start,int end){sendPacketCommand("ALL","schedule",0,enabled,start,end);}
 private void sendPacketCommand(String target,String cmd,int minutes,boolean enabled,int start,int end){new Thread(()->{try{JSONObject o=new JSONObject();o.put("app","REC_BATTERY_V4");o.put("target",target);o.put("cmd",cmd);if(minutes>0)o.put("minutes",minutes);if("schedule".equals(cmd)){o.put("enabled",enabled);o.put("startMin",start);o.put("endMin",end);}byte[] d=o.toString().getBytes(StandardCharsets.UTF_8);try(DatagramSocket s=new DatagramSocket()){s.setBroadcast(true);DatagramPacket p=new DatagramPacket(d,d.length,InetAddress.getByName("255.255.255.255"),BatteryBroadcastService.PORT+1);for(int x=0;x<5;x++){s.send(p);Thread.sleep(150);}}}catch(Exception ignored){}}).start();}
 private final Runnable refresh=new Runnable(){public void run(){if("monitor".equals(Prefs.getRole(MainActivity.this)))render();else renderSelf();ui.postDelayed(this,1000);}};
 private void renderSelf(){if(selfStatus==null)return;long end=Prefs.getTimerEnd(this),left=end-System.currentTimeMillis();if(left>0){selfStatus.setText("Pemantauan aktif • Timer "+formatDuration(left));selfStatus.setTextColor(Color.rgb(22,120,60));}else{selfStatus.setText(Prefs.inSchedule(this)?"Pemantauan aktif":"Di luar waktu pemantauan");selfStatus.setTextColor(Prefs.inSchedule(this)?Color.rgb(22,120,60):Color.GRAY);}}
 private void render(){if(list==null)return;List<DeviceInfo> data; synchronized(devices){data=new ArrayList<>(devices.values());}data.sort(Comparator.comparingInt(a->a.battery<0?101:a.battery));list.removeAllViews();long now=System.currentTimeMillis();int threshold=Prefs.getThreshold(this),online=0;for(DeviceInfo d:data)if(now-d.lastSeen<=Math.max(60,Prefs.getInterval(this)*4)*1000L)online++;subtitle.setText(online+" online • "+data.size()+" dipaparkan • amaran ≤ "+threshold+"%");for(DeviceInfo d:data){boolean on=now-d.lastSeen<=Math.max(60,Prefs.getInterval(this)*4)*1000L;if(weakOnly&&on&&d.battery>threshold)continue;if(on&&d.battery>=0&&d.battery<=threshold&&!d.charging){if(!alerted.contains(d.id)){alerted.add(d.id);alarm();}}else if(d.battery>threshold||d.charging)alerted.remove(d.id);LinearLayout c=card();LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);LinearLayout left=new LinearLayout(this);left.setOrientation(LinearLayout.VERTICAL);left.addView(tv(d.name,20,Color.rgb(15,23,42),true));left.addView(tv(d.model+" • "+age(now-d.lastSeen),12,Color.GRAY,false));row.addView(left,new LinearLayout.LayoutParams(0,-2,1));int col=!on?Color.GRAY:d.battery<=20?Color.rgb(220,38,38):d.battery<=40?Color.rgb(217,119,6):Color.rgb(22,163,74);row.addView(tv((d.battery<0?"--":d.battery)+"%",30,col,true));c.addView(row);String st=!on?"OFFLINE • bacaan terakhir":(d.charging?"⚡ SEDANG DICAS":"● ONLINE");if(d.timerEnd>now)st+=" • ⏱ "+formatDuration(d.timerEnd-now);c.addView(tv(st,12,on?Color.DKGRAY:Color.GRAY,true));LinearLayout buttons=new LinearLayout(this);Button timer=button(d.timerEnd>now?"Batal Timer":"Timer");timer.setOnClickListener(v->{if(d.timerEnd>System.currentTimeMillis())sendSimpleCommand(d.id,"clearTimer",0);else timerDialog(d);});buttons.addView(timer,new LinearLayout.LayoutParams(0,-2,1));Button r=button("Refresh");r.setOnClickListener(v->sendSimpleCommand(d.id,"refresh",0));buttons.addView(r,new LinearLayout.LayoutParams(0,-2,1));Button del=button("Padam");del.setOnClickListener(v->confirmDelete(d));buttons.addView(del,new LinearLayout.LayoutParams(0,-2,1));c.addView(buttons);list.addView(c);}if(list.getChildCount()==0){LinearLayout c=card();c.addView(tv(weakOnly?"Tiada tablet lemah":"Belum ada tablet dikesan",18,Color.DKGRAY,true));list.addView(c);}}
 private void confirmDelete(DeviceInfo d){new AlertDialog.Builder(this).setTitle("Padam "+d.name+"?").setMessage("Tablet ini akan disembunyikan daripada monitor ini. Boleh dipulihkan kemudian.").setPositiveButton("Padam",(x,w)->{Prefs.hideDevice(this,d.id);devices.remove(d.id);alerted.remove(d.id);render();}).setNegativeButton("Batal",null).show();}
 private void timerDialog(DeviceInfo d){EditText e=num("");e.setHint("Contoh: 30");new AlertDialog.Builder(this).setTitle("Timer • "+d.name).setMessage("Bila tamat, tablet akan bunyi dan paparkan MASA TAMAT di atas app lain jika kebenaran overlay telah diberi.").setView(e).setPositiveButton("Mula",(x,w)->{try{sendSimpleCommand(d.id,"timer",Integer.parseInt(e.getText().toString()));}catch(Exception ignored){}}).setNegativeButton("Batal",null).show();}
 private void alarm(){final int ms=Prefs.getAlarmSeconds(this)*1000;new Thread(()->{ToneGenerator tg=null;try{AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);am.setStreamVolume(AudioManager.STREAM_ALARM,am.getStreamMaxVolume(AudioManager.STREAM_ALARM),0);tg=new ToneGenerator(AudioManager.STREAM_ALARM,100);long until=System.currentTimeMillis()+ms;while(System.currentTimeMillis()<until){tg.startTone(ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD,900);Thread.sleep(1000);}}catch(Exception ignored){}finally{if(tg!=null)tg.release();}}).start();}
 private String formatDuration(long ms){long sec=Math.max(0,ms/1000),m=sec/60,s=sec%60;return String.format(Locale.US,"%02d:%02d",m,s);}private String age(long ms){long s=Math.max(0,ms/1000);return s<5?"sekarang":s<60?s+"s lalu":(s/60)+"m lalu";}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(15),dp(16),dp(15));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(16));bg.setStroke(dp(1),Color.LTGRAY);c.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(6));c.setLayoutParams(lp);return c;}private TextView tv(String t,int sp,int col,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(sp);v.setTextColor(col);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}private Button button(String t){Button b=new Button(this);b.setText(t);b.setAllCaps(false);return b;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
 @Override protected void onDestroy(){listening=false;ui.removeCallbacks(refresh);if(socket!=null)socket.close();if(lock!=null&&lock.isHeld())lock.release();super.onDestroy();}
}
